// Code that only a vector written at run time reaches, as an IRQ handler or a
// dispatched routine is: static analysis cannot see that $0820 runs, coverage can.
//   $080d  LDA #$20 / STA $0300 / LDA #$08 / STA $0301 / JMP ($0300)
//   $0820  INC $d020 / JMP $0820

export const VECTORED_ROUTINE = 0x0820;

export const vectoredPrg = Uint8Array.from([
  0x01, 0x08, // load address $0801
  0x0b, 0x08, 0x0a, 0x00, 0x9e, 0x32, 0x30, 0x36, 0x31, 0x00, 0x00, 0x00, // 10 SYS2061
  0xa9, 0x20, 0x8d, 0x00, 0x03, // $080d
  0xa9, 0x08, 0x8d, 0x01, 0x03, // $0812
  0x6c, 0x00, 0x03, // $0817: JMP ($0300)
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // $081a: not used
  0xee, 0x20, 0xd0, // $0820: INC $d020
  0x4c, 0x20, 0x08, // $0823: JMP $0820
]);
